const { contextBridge, ipcMain } = require('electron');

contextBridge.exposeInMainWorld('electron', {
  getDownloadsPath: () => require('electron').app.getPath('downloads'),
});

const express = require('express');
const session = require('express-session');
const axios = require('axios');
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 5000;

app.use(express.json());
app.use(session({
  secret: process.env.SESSION_SECRET || 'your-secret-key',
  resave: false,
  saveUninitialized: true,
}));

// OAuth Routes
const redditRouter = require('./routes/reddit');
const imgurRouter = require('./routes/imgur');
const dropboxRouter = require('./routes/dropbox');

app.use('/oauth/reddit', redditRouter);
app.use('/oauth/imgur', imgurRouter);
app.use('/oauth/dropbox', dropboxRouter);

// Media routes
const redditMediaRouter = require('./routes/media/reddit');
const imgurMediaRouter = require('./routes/media/imgur');
const dropboxMediaRouter = require('./routes/media/dropbox');

app.use('/api/reddit', redditMediaRouter);
app.use('/api/imgur', imgurMediaRouter);
app.use('/api/dropbox', dropboxMediaRouter);

// Health check
app.get('/api/health', (req, res) => {
  res.json({ status: 'ok' });
});

const startServer = () => {
  app.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
};

module.exports = startServer;

