const express = require('express');
const axios = require('axios');
const router = express.Router();

const REDDIT_AUTH_URL = 'https://www.reddit.com/api/v1/authorize';
const REDDIT_TOKEN_URL = 'https://www.reddit.com/api/v1/access_token';

router.get('/login', (req, res) => {
  const clientId = process.env.REDDIT_CLIENT_ID;
  const redirectUri = process.env.REDDIT_REDIRECT_URI;
  const state = Math.random().toString(36).substring(7);

  req.session.oauthState = state;

  const authUrl = `${REDDIT_AUTH_URL}?client_id=${clientId}&response_type=code&state=${state}&redirect_uri=${redirectUri}&duration=permanent&scope=read,history`;

  res.json({ authUrl });
});

router.get('/callback', async (req, res) => {
  const { code, state } = req.query;

  if (state !== req.session.oauthState) {
    return res.status(400).json({ error: 'Invalid state' });
  }

  try {
    const response = await axios.post(REDDIT_TOKEN_URL, {
      grant_type: 'authorization_code',
      code,
      redirect_uri: process.env.REDDIT_REDIRECT_URI,
    }, {
      auth: {
        username: process.env.REDDIT_CLIENT_ID,
        password: process.env.REDDIT_CLIENT_SECRET,
      },
      headers: {
        'User-Agent': 'MediaScraper/0.1.0',
      },
    });

    req.session.redditToken = response.data.access_token;
    req.session.redditRefreshToken = response.data.refresh_token;

    res.redirect('http://localhost:3000/dashboard?service=reddit&authenticated=true');
  } catch (error) {
    console.error('Reddit OAuth error:', error.message);
    res.redirect('http://localhost:3000/dashboard?service=reddit&error=true');
  }
});

router.get('/logout', (req, res) => {
  delete req.session.redditToken;
  delete req.session.redditRefreshToken;
  res.json({ success: true });
});

router.get('/status', (req, res) => {
  res.json({ authenticated: !!req.session.redditToken });
});

module.exports = router;

