const express = require('express');
const axios = require('axios');
const fs = require('fs');
const path = require('path');
const router = express.Router();

const REDDIT_API = 'https://oauth.reddit.com';

// Get subreddit posts with media
router.post('/search', async (req, res) => {
  const { subreddit, limit = 25, sort = 'hot' } = req.body;
  const token = req.session.redditToken;

  if (!token) {
    return res.status(401).json({ error: 'Not authenticated' });
  }

  try {
    const response = await axios.get(
      `${REDDIT_API}/r/${subreddit}/${sort}`,
      {
        headers: {
          Authorization: `Bearer ${token}`,
          'User-Agent': 'MediaScraper/0.1.0',
        },
        params: { limit },
      }
    );

    const posts = response.data.data.children
      .map(child => child.data)
      .filter(post => {
        const mediaTypes = ['image', 'video', 'gifsicle'];
        return mediaTypes.some(type => post.post_hint?.includes(type)) || post.media || post.is_video;
      })
      .map(post => ({
        id: post.id,
        title: post.title,
        url: post.url,
        thumbnail: post.thumbnail,
        author: post.author,
        created: post.created_utc,
        is_video: post.is_video,
        post_hint: post.post_hint,
      }));

    res.json({ posts });
  } catch (error) {
    console.error('Reddit search error:', error.message);
    res.status(500).json({ error: error.message });
  }
});

// Download media
router.post('/download', async (req, res) => {
  const { url, filename } = req.body;
  const token = req.session.redditToken;

  if (!token) {
    return res.status(401).json({ error: 'Not authenticated' });
  }

  try {
    const response = await axios.get(url, {
      responseType: 'stream',
      headers: {
        'User-Agent': 'MediaScraper/0.1.0',
      },
    });

    const downloadPath = path.join(require('electron').app.getPath('downloads'), 'media-scraper', filename);

    fs.mkdirSync(path.dirname(downloadPath), { recursive: true });

    const writer = fs.createWriteStream(downloadPath);
    response.data.pipe(writer);

    writer.on('finish', () => {
      res.json({ success: true, path: downloadPath });
    });

    writer.on('error', (err) => {
      res.status(500).json({ error: err.message });
    });
  } catch (error) {
    console.error('Download error:', error.message);
    res.status(500).json({ error: error.message });
  }
});

module.exports = router;

