const express = require('express');
const axios = require('axios');
const fs = require('fs');
const path = require('path');
const router = express.Router();

const IMGUR_API = 'https://api.imgur.com/3';

// Get user albums
router.get('/albums', async (req, res) => {
  const token = req.session.imgurToken;

  if (!token) {
    return res.status(401).json({ error: 'Not authenticated' });
  }

  try {
    const response = await axios.get(`${IMGUR_API}/account/me/albums`, {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });

    const albums = response.data.data.map(album => ({
      id: album.id,
      title: album.title,
      description: album.description,
      cover: album.cover,
      images_count: album.images_count,
    }));

    res.json({ albums });
  } catch (error) {
    console.error('Imgur albums error:', error.message);
    res.status(500).json({ error: error.message });
  }
});

// Get album images
router.post('/album-images', async (req, res) => {
  const { albumId } = req.body;
  const token = req.session.imgurToken;

  if (!token) {
    return res.status(401).json({ error: 'Not authenticated' });
  }

  try {
    const response = await axios.get(`${IMGUR_API}/album/${albumId}/images`, {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });

    const images = response.data.data.map(image => ({
      id: image.id,
      title: image.title,
      description: image.description,
      url: image.link,
      type: image.type,
      size: image.size,
    }));

    res.json({ images });
  } catch (error) {
    console.error('Imgur images error:', error.message);
    res.status(500).json({ error: error.message });
  }
});

// Search gallery
router.post('/search', async (req, res) => {
  const { query, sort = 'time', limit = 25 } = req.body;
  const token = req.session.imgurToken;

  if (!token) {
    return res.status(401).json({ error: 'Not authenticated' });
  }

  try {
    const response = await axios.get(`${IMGUR_API}/gallery/search/${sort}`, {
      headers: {
        Authorization: `Bearer ${token}`,
      },
