const express = require('express');
const axios = require('axios');
const fs = require('fs');
const path = require('path');
const router = express.Router();

const DROPBOX_API = 'https://api.dropboxapi.com/2';

// List folder contents
router.post('/list-folder', async (req, res) => {
  const { folderPath = '/' } = req.body;
  const token = req.session.dropboxToken;

  if (!token) {
    return res.status(401).json({ error: 'Not authenticated' });
  }

  try {
    const response = await axios.post(`${DROPBOX_API}/files/list_folder`, {
      path: folderPath,
      recursive: false,
    }, {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });

    const entries = response.data.entries
      .filter(entry => entry['.tag'] === 'file')
      .filter(entry => {
        const mediaExtensions = ['.jpg', '.jpeg', '.png', '.gif', '.mp4', '.mov', '.webm', '.mkv'];
        return mediaExtensions.some(ext => entry.name.toLowerCase().endsWith(ext));
      })
      .map(entry => ({
        name: entry.name,
        path_display: entry.path_display,
        size: entry.size,
        modified: entry.server_modified,
      }));

    res.json({ entries });
  } catch (error) {
    console.error('Dropbox list error:', error.message);
    res.status(500).json({ error: error.message });
  }
});

// Search files
router.post('/search', async (req, res) => {
  const { query, folderPath = '/' } = req.body;
  const token = req.session.dropboxToken;

  if (!token) {
    return res.status(401).json({ error: 'Not authenticated' });
  }

  try {
    const response = await axios.post(`${DROPBOX_API}/files/search_v2`, {
      query,
      options: {
        path: folderPath,
        max_results: 25,
      },
    }, {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });

    const matches = response.data.matches
      .filter(match => match.metadata.metadata['.tag'] === 'file')
      .filter(match => {
        const mediaExtensions = ['.jpg', '.jpeg', '.png', '.gif', '.mp4', '.mov', '.webm', '.mkv'];
        const name = match.metadata.metadata.name;
        return mediaExtensions.some(ext => name.toLowerCase().endsWith(ext));
      })
      .map(match => {
        const meta = match.metadata.metadata;
        return {
          name: meta.name,
          path_display: meta.path_display,
          size: meta.size,
          modified: meta.server_modified,
        };
      });

    res.json({ matches });
  } catch (error) {
    console.error('Dropbox search error:', error.message);
    res.status(500).json({ error: error.message });
  }
});

// Download file
router.post('/download', async (req, res) => {
  const { filePath, filename } = req.body;
  const token = req.session.dropboxToken;

  if (!token) {
    return res.status(401).json({ error: 'Not authenticated' });
  }

  try {
    const response = await axios.post(
      'https://content.dropboxapi.com/2/files/download',
      null,
      {
        responseType: 'stream',
        headers: {
          Authorization: `Bearer ${token}`,
          'Dropbox-API-Arg': JSON.stringify({ path: filePath }),
        },
      }
    );

    const downloadPath = path.join(require('electron').app.getPath('downloads'), 'media-scraper', filename);

    fs.mkdirSync(path.dirname(downloadPath), { recursive: true });

    const writer = fs.createWriteStream(downloadPath);
    response.data.pipe(writer);

    writer.on('finish', () => {
      res.json({ success: true, path: downloadPath });
    });

    writer.on('error', (err) => {
      res.status(500).json({ error: err.message });
    });
  } catch (error) {
    console.error('Download error:', error.message);
    res.status(500).json({ error: error.message });
  }
});

module.exports = router;

