import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import './Login.css';

function Login() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);

  const handleLogin = async (service) => {
    setLoading(true);
    try {
      const response = await axios.get(`http://localhost:5000/oauth/${service}/login`);
      window.location.href = response.data.authUrl;
    } catch (error) {
      console.error(`Error logging in to ${service}:`, error);
      alert(`Failed to login to ${service}`);
      setLoading(false);
    }
  };

  return (
    <div className="login-container">
      <div className="login-box">
        <h1>Media Scraper</h1>
        <p>Select a platform to log in</p>

        <div className="login-buttons">
          <button
            className="login-btn reddit-btn"
            onClick={() => handleLogin('reddit')}
            disabled={loading}
          >
            <span className="logo">🔴</span>
            Login with Reddit
          </button>

          <button
            className="login-btn imgur-btn"
            onClick={() => handleLogin('imgur')}
            disabled={loading}
          >
            <span className="logo">🖼</span>
            Login with Imgur
          </button>

          <button
            className="login-btn dropbox-btn"
            onClick={() => handleLogin('dropbox')}
            disabled={loading}
          >
            <span className="logo">☁️</span>
            Login with Dropbox
          </button>
        </div>
      </div>
    </div>
  );
}

export default Login;

