import React, { useState } from 'react';
import axios from 'axios';
import MediaGrid from './MediaGrid';
import './Tab.css';

function RedditTab({ authenticated, onLogin, onLogout }) {
  const [subreddit, setSubreddit] = useState('');
  const [sort, setSort] = useState('hot');
  const [limit, setLimit] = useState(25);
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [selectedPosts, setSelectedPosts] = useState(new Set());
  const [downloading, setDownloading] = useState(false);

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!subreddit.trim()) {
      setError('Please enter a subreddit name');
      return;
    }

    setLoading(true);
    setError('');
    setPosts([]);
    setSelectedPosts(new Set());

    try {
      const response = await axios.post('http://localhost:5000/api/reddit/search', {
        subreddit: subreddit.trim(),
        sort,
        limit,
      });
      setPosts(response.data.posts);
    } catch (err) {
      setError(err.response?.data?.error || 'Error fetching posts');
    } finally {
      setLoading(false);
    }
  };

  const togglePostSelection = (postId) => {
    const newSelected = new Set(selectedPosts);
    if (newSelected.has(postId)) {
      newSelected.delete(postId);
    } else {
      newSelected.add(postId);
    }
    setSelectedPosts(newSelected);
  };

  const handleDownload = async () => {
    if (selectedPosts.size === 0) {
      alert('Please select at least one post to download');
      return;
    }

    setDownloading(true);
    const selectedPostsArray = posts.filter(p => selectedPosts.has(p.id));

    for (const post of selectedPostsArray) {
      try {
        await axios.post('http://localhost:5000/api/reddit/download', {
          url: post.url,
          filename: `reddit_${post.id}.jpg`,
        });
      } catch (err) {
        console.error(`Error downloading ${post.id}:`, err);
      }
    }

    setDownloading(false);
    alert(`Downloaded ${selectedPostsArray.length} items`);
    setSelectedPosts(new Set());
  };

  if (!authenticated) {
    return (
      <div className="tab-container">
        <div className="auth-message">
          <p>Not authenticated</p>
          <button className="primary-btn" onClick={onLogin}>
            Login with Reddit
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="tab-container">
      <form onSubmit={handleSearch} className="search-form">
        <div className="form-group">
          <label>Subreddit</label>
          <input
            type="text"
            placeholder="e.g., earthporn, photography"
            value={subreddit}
            onChange={(e) => setSubreddit(e.target.value)}
          />
        </div>

        <div className="form-group">
          <label>Sort by</label>
          <select value={sort} onChange={(e) => setSort(e.target.value)}>
            <option value="hot">Hot</option>
            <option value="new">New</option>
            <option value="top">Top</option>
          </select>
        </div>

        <div className="form-group">
          <label>Limit</label>
          <input
            type="number"
            min="1"
            max="100"
            value={limit}
            onChange={(e) => setLimit(parseInt(e.target.value))}
          />
        </div>

        <button type="submit" className="primary-btn" disabled={loading}>
          {loading ? 'Searching...' : 'Search'}
        </button>

        <button type="button" className="danger-btn" onClick={onLogout}>
          Logout
        </button>
      </form>

      {error && <div className="error-message">{error}</div>}

      {posts.length > 0 && (
        <div className="results-section">
          <div className="results-header">
            <h2>Results ({posts.length})</h2>
            <div className="selection-controls">
              <span>{selectedPosts.size} selected</span>
              <button
                className="primary-btn"
                onClick={handleDownload}
                disabled={selectedPosts.size === 0 || downloading}
              >
                {downloading ? 'Downloading...' : `Download (${selectedPosts.size})`}
              </button>
            </div>
          </div>

          <MediaGrid
            items={posts}
            selectedItems={selectedPosts}
            onToggleSelection={togglePostSelection}
            renderItem={(post) => (
              <div className="media-item">
                {post.thumbnail && post.thumbnail !== 'self' && (
                  <img src={post.thumbnail} alt={post.title} />
                )}
                <div className="media-info">
                  <p className="media-title">{post.title}</p>
                  <p className="media-author">u/{post.author}</p>
                </div>
              </div>
            )}
          />
        </div>
      )}
    </div>
  );
}

export default RedditTab;

