import React, { useState, useEffect } from 'react';
import axios from 'axios';
import MediaGrid from './MediaGrid';
import './Tab.css';

function ImgurTab({ authenticated, onLogin, onLogout }) {
  const [activeSection, setActiveSection] = useState('albums');
  const [albums, setAlbums] = useState([]);
  const [images, setImages] = useState([]);
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [selectedItems, setSelectedItems] = useState(new Set());
  const [downloading, setDownloading] = useState(false);

  useEffect(() => {
    if (authenticated && activeSection === 'albums') {
      loadAlbums();
    }
  }, [authenticated, activeSection]);

  const loadAlbums = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await axios.get('http://localhost:5000/api/imgur/albums');
      setAlbums(response.data.albums);
    } catch (err) {
      setError(err.response?.data?.error || 'Error loading albums');
    } finally {
      setLoading(false);
    }
  };

  const handleAlbumClick = async (albumId) => {
    setLoading(true);
    setError('');
    try {
      const response = await axios.post(
        'http://localhost:5000/api/imgur/album-images',
        { albumId }
      );
      setImages(response.data.images);
      setSelectedItems(new Set());
    } catch (err) {
      setError(err.response?.data?.error || 'Error loading album images');
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!query.trim()) {
      setError('Please enter a search query');
      return;
    }

    setLoading(true);
    setError('');
    try {
      const response = await axios.post('http://localhost:5000/api/imgur/search', {
        query: query.trim(),
      });
      setImages(response.data.items);
      setSelectedItems(new Set());
    } catch (err) {
      setError(err.response?.data?.error || 'Error searching');
    } finally {
      setLoading(false);
    }
  };

  const toggleSelection = (itemId) => {
    const newSelected = new Set(selectedItems);
    if (newSelected.has(itemId)) {
      newSelected.delete(itemId);
    } else {
      newSelected.add(itemId);
    }
    setSelectedItems(newSelected);
  };

  const handleDownload = async () => {
    if (selectedItems.size === 0) {
      alert('Please select at least one image to download');
      return;
    }

    setDownloading(true);
    const selectedArray = images.filter(i => selectedItems.has(i.id));

    for (const item of selectedArray) {
      try {
        await axios.post('http://localhost:5000/api/imgur/download', {
          url: item.url,
          filename: `imgur_${item.id}.jpg`,
        });
      } catch (err) {
        console.error(`Error downloading ${item.id}:`, err);
      }
    }

    setDownloading(false);
    alert(`Downloaded ${selectedArray.length} items`);
    setSelectedItems(new Set());
  };

  if (!authenticated) {
    return (
      <div className="tab-container">
        <div className="auth-message">
          <p>Not authenticated</p>
          <button className="primary-btn" onClick={onLogin}>
            Login with Imgur
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="tab-container">
      <div className="section-controls">
        <button
          className={`section-btn ${activeSection === 'albums' ? 'active' : ''}`}
          onClick={() => setActiveSection('albums')}
        >
          My Albums
        </button>
        <button
          className={`section-btn ${activeSection === 'search' ? 'active' : ''}`}
          onClick={() => setActiveSection('search')}
        >
          Search Gallery
        </button>
        <button type="button" className="danger-btn" onClick={onLogout}>
          Logout
        </button>
      </div>

      {activeSection === 'search' && (
        <form onSubmit={handleSearch} className="search-form">
          <div className="form-group">
            <label>Search</label>
            <input
              type="text"
              placeholder="e.g., cats, landscapes"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
            />
          </div>
          <button type="submit" className="primary-btn" disabled={loading}>
            {loading ? 'Searching...' : 'Search'}
          </button>
        </form>
      )}

      {error && <div className="error-message">{error}</div>}

      {activeSection === 'albums' && (
        <div className="results-section">
          <h2>My Albums</h2>
          {loading ? (
            <p>Loading albums...</p>
          ) : (
            <MediaGrid
              items={albums}
              selectedItems={selectedItems}
              onToggleSelection={toggleSelection}
              renderItem={(album) => (
                <div className="media-item" onClick={() => handleAlbumClick(album.id)}>
                  {album.cover && (
                    <img src={`https://imgur.com/${album.cover}.jpg`} alt={album.title} />
                  )}
                  <div className="media-info">
                    <p className="media-title">{album.title}</p>
                    <p className="media-author">{album.images_count} images</p>
                  </div>
                </div>
              )}
            />
          )}
        </div>
      )}

      {images.length > 0 && (
        <div className="results-section">
          <div className="results-header">
            <h2>Images ({images.length})</h2>
            <div className="selection-controls">
              <span>{selectedItems.size} selected</span>
              <button
                className="primary-btn"
                onClick={handleDownload}
                disabled={selectedItems.size === 0 || downloading}
              >
                {downloading ? 'Downloading...' : `Download (${selectedItems.size})`}
              </button>
            </div>
          </div>

          <MediaGrid
            items={images}
            selectedItems={selectedItems}
            onToggleSelection={toggleSelection}
            renderItem={(image) => (
              <div className="media-item">
                <img src={image.url} alt={image.title} />
                <div className="media-info">
                  <p className="media-title">{image.title || 'Untitled'}</p>
                </div>
              </div>
            )}
          />
        </div>
      )}
    </div>
  );
}

export default ImgurTab;

