import React, { useState } from 'react';
import axios from 'axios';
import MediaGrid from './MediaGrid';
import './Tab.css';

function DropboxTab({ authenticated, onLogin, onLogout }) {
  const [folderPath, setFolderPath] = useState('/');
  const [searchQuery, setSearchQuery] = useState('');
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [selectedFiles, setSelectedFiles] = useState(new Set());
  const [downloading, setDownloading] = useState(false);
  const [useSearch, setUseSearch] = useState(false);

  const handleBrowse = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSelectedFiles(new Set());

    try {
      const response = await axios.post(
        'http://localhost:5000/api/dropbox/list-folder',
        { folderPath }
      );
      setFiles(response.data.entries);
      setUseSearch(false);
    } catch (err) {
      setError(err.response?.data?.error || 'Error browsing folder');
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!searchQuery.trim()) {
      setError('Please enter a search query');
      return;
    }

    setLoading(true);
    setError('');
    setSelectedFiles(new Set());

    try {
      const response = await axios.post(
        'http://localhost:5000/api/dropbox/search',
        { query: searchQuery.trim(), folderPath }
      );
      setFiles(response.data.matches);
      setUseSearch(true);
    } catch (err) {
      setError(err.response?.data?.error || 'Error searching');
    } finally {
      setLoading(false);
    }
  };

  const toggleFileSelection = (filePath) => {
    const newSelected = new Set(selectedFiles);
    if (newSelected.has(filePath)) {
      newSelected.delete(filePath);
    } else {
      newSelected.add(filePath);
    }
    setSelectedFiles(newSelected);
  };

  const handleDownload = async () => {
    if (selectedFiles.size === 0) {
      alert('Please select at least one file to download');
      return;
    }

    setDownloading(true);
    const selectedArray = files.filter(f => selectedFiles.has(f.path_display));

    for (const file of selectedArray) {
      try {
        await axios.post('http://localhost:5000/api/dropbox/download', {
          filePath: file.path_display,
          filename: file.name,
        });
      } catch (err) {
        console.error(`Error downloading ${file.name}:`, err);
      }
    }

    setDownloading(false);
    alert(`Downloaded ${selectedArray.length} files`);
    setSelectedFiles(new Set());
  };

  if (!authenticated) {
    return (
      <div className="tab-container">
        <div className="auth-message">
          <p>Not authenticated</p>
          <button className="primary-btn" onClick={onLogin}>
            Login with Dropbox
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="tab-container">
      <div className="tab-controls">
        <form onSubmit={handleBrowse} className="search-form">
          <div className="form-group">
            <label>Folder Path</label>
            <input
              type="text"
              placeholder="e.g., /Photos, /Videos"
              value={folderPath}
              onChange={(e) => setFolderPath(e.target.value)}
            />
          </div>
          <button type="submit" className="primary-btn" disabled={loading}>
            {loading ? 'Browsing...' : 'Browse'}
          </button>
        </form>

        <div className="divider">or</div>

        <form onSubmit={handleSearch} className="search-form">
          <div className="form-group">
            <label>Search Files</label>
            <input
              type="text"
              placeholder="e.g., vacation, birthday"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <button type="submit" className="primary-btn" disabled={loading}>
            {loading ? 'Searching...' : 'Search'}
          </button>
        </form>

        <button type="button" className="danger-btn" onClick={onLogout}>
          Logout
        </button>
      </div>

      {error && <div className="error-message">{error}</div>}

      {files.length > 0 && (
        <div className="results-section">
          <div className="results-header">
            <h2>
              {useSearch ? 'Search Results' : `Folder: ${folderPath}`} ({files.length})
            </h2>
            <div className="selection-controls">
              <span>{selectedFiles.size} selected</span>
              <button
                className="primary-btn"
                onClick={handleDownload}
                disabled={selectedFiles.size === 0 || downloading}
              >
                {downloading ? 'Downloading...' : `Download (${selectedFiles.size})`}
              </button>
            </div>
          </div>

          <div className="file-list">
            {files.map((file) => (
              <div
                key={file.path_display}
                className={`file-item ${selectedFiles.has(file.path_display) ? 'selected' : ''}`}
                onClick={() => toggleFileSelection(file.path_display)}
              >
                <input
                  type="checkbox"
                  checked={selectedFiles.has(file.path_display)}
                  onChange={() => toggleFileSelection(file.path_display)}
                  onClick={(e) => e.stopPropagation()}
                />
                <span className="file-name">{file.name}</span>
                <span className="file-size">
                  {(file.size / 1024 / 1024).toFixed(2)} MB
                </span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

export default DropboxTab;

