.media-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 15px;
  margin-top: 20px;
}

.grid-item {
  position: relative;
  border: 2px solid #e0e0e0;
  border-radius: 8px;
  overflow: hidden;
  cursor: pointer;
  transition: all 0.2s;
  background: white;
}

.grid-item:hover {
  border-color: #1e90ff;
  box-shadow: 0 4px 12px rgba(30, 144, 255, 0.2);
  transform: translateY(-2px);
}

.grid-item.selected {
  border-color: #1e90ff;
  background-color: #f0f4ff;
}

.item-checkbox {
  position: absolute;
  top: 8px;
  right: 8px;
  z-index: 10;
  background: white;
  border-radius: 4px;
  padding: 4px;
}

.item-checkbox input[type='checkbox'] {
  cursor: pointer;
  width: 18px;
  height: 18px;
}

.media-item {
  display: flex;
  flex-direction: column;
  height: 100%;
  width: 100%;
}

.media-item img {
  width: 100%;
  height: 120px;
  object-fit: cover;
  background: #f0f0f0;
}

.media-info {
  padding: 10px;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.media-title {
  font-size: 12px;
  font-weight: 600;
  margin: 0 0 4px 0;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  color: #333;
}

.media-author {
  font-size: 11px;
  color: #999;
  margin: 0;
}

